5. **Implement JavaScript**:
   ```javascript
   const timerDisplay = document.querySelector('.timer');
   const buttons = document.querySelectorAll('button');
   let timeLeft = 25 * 60; // 25 minutes in seconds
   let intervalId = null;
   let isRunning = false;

   function updateDisplay(seconds) {
     const minutes = Math.floor(seconds / 60);
     const secondsLeft = seconds % 60;
     timerDisplay.textContent = `${minutes}:${secondsLeft.toString().padStart(2, '0')}`;
   }

   function startTimer() {
     if (!isRunning) {
       intervalId = setInterval(() => {
         timeLeft--;
         updateDisplay(timeLeft);
         if (timeLeft === 0) {
           clearInterval(intervalId);
           isRunning = false;
           // Add sound notification here
           new Audio('https://assets.mixkit.co/active_storage/sfx/2566/2566-preview.mp3').play();
           // Reset timer after 5 minutes for break
           setTimeout(() => {
             timeLeft = 5 * 60;
             updateDisplay(timeLeft);
             intervalId = setInterval(() => {
               timeLeft--;
               updateDisplay(timeLeft);
               if (timeLeft === 0) {
                 clearInterval(intervalId);
                 isRunning = false;
                 new Audio('https://assets.mixkit.co/active_storage/sfx/2566/2566-preview.mp3').play();
               }
             }, 1000);
           }, 30000);
         }
       }, 1000);
       isRunning = true;
     }
   }

   function pauseTimer() {
     clearInterval(intervalId);
     isRunning = false;
   }

   function resetTimer() {
     clearInterval(intervalId);
     timeLeft = 25 * 60;
     updateDisplay(timeLeft);
     isRunning = false;
   }

   buttons.forEach(button => {
     button.addEventListener('click', () => {
       if (button.id === 'start') startTimer();
       if (button.id === 'pause') pauseTimer();
       if (button.id === 'reset') resetTimer();
     });
   });
   ```

